```tsx
import { useSession, signIn, signOut } from "next-auth/react";
import { useRouter } from "next/router";
import { useEffect } from "react";

export default function Auth() {
  const { data: session, status } = useSession();
  const router = useRouter();

  useEffect(() => {
    if (status === "loading") return; // Do nothing while loading
    if (!session) {
      // If no session, redirect to login page
      router.push("/login");
    }
  }, [session, status, router]);

  if (status === "loading") {
    return <div>Loading...</div>;
  }

  if (!session) {
    return (
      <div>
        <h1>Not logged in</h1>
        <button onClick={() => signIn()}>Sign In</button>
      </div>
    );
  }

  return (
    <div>
      <h1>Welcome, {session.user?.name}</h1>
      <button onClick={() => signOut()}>Sign Out</button>
    </div>
  );
}
```

This component uses the `useSession` hook from `next-auth/react` to get the current session and the `signIn` and `signOut` functions to handle authentication. It also uses the `useRouter` hook from `next/router` to redirect the user to the login page if they are not authenticated. The component displays a loading message while the session is being fetched, and a sign-in button if the user is not logged in. If the user is logged in, it displays a welcome message and a sign-out button.

